mapper.update:
update orders
set status     = #{status},
    pay_status = #{payStatus}
where number = #{number}

mapper.select:
select number, pay_type, pay_status, amount
from orders
where number = #{number}

select id, number, status, user_id, address_book_id, order_time, checkout_time,
       order_type, pay_type, pay_status, amount, table_number, tableware_number,
       remark, pack_amount, rejection_reason, consignee, cancel_time
from orders


        and user_id = #{userId}


        and number = #{number}


        and status = #{status}


        and order_time >= #{beginTime}


        and order_time <= #{endTime}


order by order_time desc

    limit #{pageSize} offset #{page}
